  "kidsPrayer.subtitle": { fr: "La prière de A à Z, pas à pas 🕌", en: "Prayer from A to Z, step by step 🕌", nl: "Het gebed van A tot Z, stap voor stap 🕌", ar: "الصلاة من الألف إلى الياء، خطوة بخطوة 🕌", tr: "Namaz A'dan Z'ye, adım adım 🕌", ur: "نماز الف سے یے تک، قدم بہ قدم 🕌" },
