  "kidsPrayer.menuStepsDesc": { fr: "Voir chaque position pas à pas", en: "See each position step by step", nl: "Bekijk elke positie stap voor stap", ar: "شاهد كل وضعية خطوة بخطوة", tr: "Her pozisyonu adım adım gör", ur: "ہر پوزیشن قدم بہ قدم دیکھیں" },
