  "kidsPrayer.menuQuizDesc": { fr: "Teste tes connaissances !", en: "Test your knowledge!", nl: "Test je kennis!", ar: "اختبر معلوماتك!", tr: "Bilgini test et!", ur: "اپنا علم آزمائیں!" },
  "kidsPrayer.comingSoon": { fr: "Bientôt disponible", en: "Coming soon", nl: "Binnenkort beschikbaar", ar: "قريباً", tr: "Yakında", ur: "جلد آ رہا ہے" },
