  "kidsPrayer.quiz.q12.opt3": { fr: "7", en: "7", nl: "7", ar: "٧", tr: "7", ur: "7" },

  // Wudu steps
  "wudu.step.niyyah.title": { fr: "L'intention (Niyyah)", en: "Intention (Niyyah)", nl: "Intentie (Niyyah)", ar: "النية", tr: "Niyet", ur: "نیت" },
  "wudu.step.niyyah.desc": { fr: "Dans ton cœur, dis que tu veux faire tes ablutions pour Allah 💚", en: "In your heart, say you want to make wudu for Allah 💚", nl: "Zeg in je hart dat je wudu wilt doen voor Allah 💚", ar: "في قلبك، انوِ أنك تريد أن تتوضأ لله 💚", tr: "Kalbinde Allah için abdest almak istediğini söyle 💚", ur: "اپنے دل میں کہیں کہ آپ اللہ کے لیے وضو کرنا چاہتے ہیں 💚" },
  "wudu.step.bismillah.title": { fr: "Bismillah", en: "Bismillah", nl: "Bismillah", ar: "بسم الله", tr: "Bismillah", ur: "بسم اللہ" },
  "wudu.step.bismillah.desc": { fr: "Dis : Bismillah (Au nom d'Allah) avant de commencer 🤲", en: "Say: Bismillah (In the name of Allah) before starting 🤲", nl: "Zeg: Bismillah (In de naam van Allah) voordat je begint 🤲", ar: "قل: بسم الله قبل أن تبدأ 🤲", tr: "Başlamadan önce de: Bismillah 🤲", ur: "شروع کرنے سے پہلے کہیں: بسم اللہ 🤲" },
  "wudu.step.hands.title": { fr: "Laver les mains (3x)", en: "Wash hands (3x)", nl: "Handen wassen (3x)", ar: "غسل اليدين (٣ مرات)", tr: "Elleri yıka (3x)", ur: "ہاتھ دھوئیں (3 بار)" },
  "wudu.step.hands.desc": { fr: "Lave tes deux mains trois fois avec de l'eau, en commençant par la droite 🖐️", en: "Wash both hands three times with water, starting with the right 🖐️", nl: "Was beide handen drie keer met water, begin met rechts 🖐️", ar: "اغسل يديك ثلاث مرات بالماء، ابدأ باليمنى 🖐️", tr: "İki elini de üçer kez yıka, sağdan başla 🖐️", ur: "دونوں ہاتھ تین بار دھوئیں، دائیں سے شروع کریں 🖐️" },
  "wudu.step.mouth.title": { fr: "Rincer la bouche (3x)", en: "Rinse mouth (3x)", nl: "Mond spoelen (3x)", ar: "المضمضة (٣ مرات)", tr: "Ağzı çalkala (3x)", ur: "کلی کریں (3 بار)" },
  "wudu.step.mouth.desc": { fr: "Prends de l'eau dans ta main droite, rince ta bouche et recrache. Trois fois ! 👄", en: "Take water in your right hand, rinse your mouth and spit out. Three times! 👄", nl: "Neem water in je rechterhand, spoel je mond en spuug uit. Drie keer! 👄", ar: "خذ ماء بيدك اليمنى، تمضمض ثم أخرج الماء. ثلاث مرات! 👄", tr: "Sağ elinle su al, ağzını çalkala ve tükür. Üç kez! 👄", ur: "دائیں ہاتھ سے پانی لیں، کلی کریں اور تھوک دیں۔ تین بار! 👄" },
  "wudu.step.nose.title": { fr: "Nettoyer le nez (3x)", en: "Clean nose (3x)", nl: "Neus reinigen (3x)", ar: "الاستنشاق (٣ مرات)", tr: "Burnu temizle (3x)", ur: "ناک صاف کریں (3 بار)" },
  "wudu.step.nose.desc": { fr: "Inspire un peu d'eau par le nez avec ta main droite, puis souffle pour la faire sortir. Trois fois ! 👃", en: "Sniff a little water into your nose with your right hand, then blow it out. Three times! 👃", nl: "Snuif een beetje water op in je neus met je rechterhand en blaas het uit. Drie keer! 👃", ar: "استنشق قليلاً من الماء بيدك اليمنى ثم انثر. ثلاث مرات! 👃", tr: "Sağ elinle biraz su çek burnuna, sonra üfle. Üç kez! 👃", ur: "دائیں ہاتھ سے تھوڑا پانی ناک میں ڈالیں، پھر باہر نکالیں۔ تین بار! 👃" },
  "wudu.step.face.title": { fr: "Laver le visage (3x)", en: "Wash face (3x)", nl: "Gezicht wassen (3x)", ar: "غسل الوجه (٣ مرات)", tr: "Yüzü yıka (3x)", ur: "چہرہ دھوئیں (3 بار)" },
  "wudu.step.face.desc": { fr: "Lave tout ton visage trois fois, du front au menton et d'une oreille à l'autre 😊", en: "Wash your whole face three times, from forehead to chin, ear to ear 😊", nl: "Was je hele gezicht drie keer, van voorhoofd tot kin, van oor tot oor 😊", ar: "اغسل وجهك كله ثلاث مرات، من الجبهة إلى الذقن ومن أذن إلى أذن 😊", tr: "Tüm yüzünü üç kez yıka, alından çeneye, kulaktan kulağa 😊", ur: "اپنا پورا چہرہ تین بار دھوئیں، پیشانی سے ٹھوڑی تک اور کان سے کان تک 😊" },
  "wudu.step.arms.title": { fr: "Laver les bras (3x)", en: "Wash arms (3x)", nl: "Armen wassen (3x)", ar: "غسل اليدين إلى المرفقين (٣ مرات)", tr: "Kolları yıka (3x)", ur: "بازو دھوئیں (3 بار)" },
  "wudu.step.arms.desc": { fr: "Lave ton bras droit jusqu'au coude trois fois, puis le gauche 💪", en: "Wash your right arm up to the elbow three times, then the left 💪", nl: "Was je rechterarm tot de elleboog drie keer, dan de linker 💪", ar: "اغسل ذراعك اليمنى إلى المرفق ثلاث مرات، ثم اليسرى 💪", tr: "Sağ kolunu dirseğe kadar üç kez yıka, sonra sol kolunu 💪", ur: "دایاں بازو کہنی تک تین بار دھوئیں، پھر بایاں 💪" },
  "wudu.step.head.title": { fr: "Essuyer la tête (1x)", en: "Wipe head (1x)", nl: "Hoofd afvegen (1x)", ar: "مسح الرأس (مرة واحدة)", tr: "Başı mesh et (1x)", ur: "سر کا مسح (1 بار)" },
  "wudu.step.head.desc": { fr: "Mouille tes mains et passe-les sur ta tête, de l'avant vers l'arrière puis reviens. Une seule fois ! 🧕", en: "Wet your hands and wipe over your head, front to back then back. Just once! 🧕", nl: "Maak je handen nat en veeg over je hoofd, van voor naar achter en terug. Eén keer! 🧕", ar: "بلل يديك وامسح رأسك من الأمام إلى الخلف ثم ارجع. مرة واحدة! 🧕", tr: "Ellerini ıslat ve başını önden arkaya mesh et, sonra geri gel. Bir kez! 🧕", ur: "ہاتھ گیلے کریں اور سر پر آگے سے پیچھے پھر واپس مسح کریں۔ صرف ایک بار! 🧕" },
  "wudu.step.ears.title": { fr: "Essuyer les oreilles (1x)", en: "Wipe ears (1x)", nl: "Oren afvegen (1x)", ar: "مسح الأذنين (مرة واحدة)", tr: "Kulakları mesh et (1x)", ur: "کانوں کا مسح (1 بار)" },
  "wudu.step.ears.desc": { fr: "Avec tes index, essuie l'intérieur de tes oreilles. Avec tes pouces, l'extérieur 👂", en: "With your index fingers, wipe inside your ears. With your thumbs, the outside 👂", nl: "Veeg met je wijsvingers de binnenkant van je oren. Met je duimen de buitenkant 👂", ar: "بسبابتيك امسح داخل أذنيك. وبإبهاميك امسح خارجهما 👂", tr: "İşaret parmaklarınla kulaklarının içini, başparmaklarınla dışını mesh et 👂", ur: "شہادت کی انگلیوں سے کانوں کے اندر اور انگوٹھوں سے باہر مسح کریں 👂" },
  "wudu.step.feet.title": { fr: "Laver les pieds (3x)", en: "Wash feet (3x)", nl: "Voeten wassen (3x)", ar: "غسل القدمين (٣ مرات)", tr: "Ayakları yıka (3x)", ur: "پاؤں دھوئیں (3 بار)" },
  "wudu.step.feet.desc": { fr: "Lave ton pied droit jusqu'à la cheville trois fois, puis le gauche. N'oublie pas entre les orteils ! 🦶", en: "Wash your right foot up to the ankle three times, then the left. Don't forget between the toes! 🦶", nl: "Was je rechtervoet tot de enkel drie keer, dan de linker. Vergeet niet tussen de tenen! 🦶", ar: "اغسل قدمك اليمنى إلى الكعب ثلاث مرات، ثم اليسرى. لا تنسَ بين الأصابع! 🦶", tr: "Sağ ayağını topuğa kadar üç kez yıka, sonra sol ayağını. Parmak aralarını unutma! 🦶", ur: "دایاں پاؤں ٹخنے تک تین بار دھوئیں، پھر بایاں۔ انگلیوں کے درمیان مت بھولیں! 🦶" },

