  "wudu.menuQuiz": { fr: "Quiz Wudu", en: "Wudu quiz", nl: "Wudu-quiz", ar: "اختبار الوضوء", tr: "Abdest testi", ur: "وضو کا امتحان" },
  "wudu.menuQuizDesc": { fr: "Teste tes connaissances sur les ablutions !", en: "Test your ablutions knowledge!", nl: "Test je kennis over wassing!", ar: "اختبر معلوماتك عن الوضوء!", tr: "Abdest bilgini test et!", ur: "وضو کے بارے میں اپنا علم آزمائیں!" },
  "wudu.quizBravo": { fr: "Bravo ! Tu connais bien le wudu 💧", en: "Bravo! You know wudu well 💧", nl: "Goed gedaan! Je kent wudu goed 💧", ar: "أحسنت! أنت تعرف الوضوء جيداً 💧", tr: "Bravo! Abdesti iyi biliyorsun 💧", ur: "شاباش! آپ وضو اچھی طرح جانتے ہیں 💧" },
  "wudu.quizTryAgain": { fr: "Continue d'apprendre le wudu ! 💪", en: "Keep learning wudu! 💪", nl: "Blijf wudu leren! 💪", ar: "واصل تعلم الوضوء! 💪", tr: "Abdest öğrenmeye devam et! 💪", ur: "وضو سیکھتے رہیں! 💪" },
  "wudu.quiz.q1": { fr: "Que dit-on avant de commencer le wudu ?", en: "What do you say before starting wudu?", nl: "Wat zeg je voor je begint met wudu?", ar: "ماذا نقول قبل بدء الوضوء؟", tr: "Abdeste başlamadan önce ne denir?", ur: "وضو شروع کرنے سے پہلے کیا کہتے ہیں؟" },
  "wudu.quiz.q1.opt1": { fr: "Bismillah", en: "Bismillah", nl: "Bismillah", ar: "بسم الله", tr: "Bismillah", ur: "بسم اللہ" },
