  "wudu.quiz.q1.opt3": { fr: "Alhamdulillah", en: "Alhamdulillah", nl: "Alhamdulillah", ar: "الحمد لله", tr: "Elhamdülillah", ur: "الحمدللہ" },
  "wudu.quiz.q2": { fr: "Combien de fois lave-t-on le visage ?", en: "How many times do you wash your face?", nl: "Hoe vaak was je je gezicht?", ar: "كم مرة نغسل الوجه؟", tr: "Yüz kaç kez yıkanır?", ur: "چہرہ کتنی بار دھوتے ہیں؟" },
