  "wudu.quiz.q3.opt3": { fr: "1 fois", en: "1 time", nl: "1 keer", ar: "مرة واحدة", tr: "1 kez", ur: "1 بار" },
  "wudu.quiz.q4": { fr: "Par quel côté commence-t-on le wudu ?", en: "Which side do you start wudu with?", nl: "Met welke kant begin je wudu?", ar: "بأي جانب نبدأ الوضوء؟", tr: "Abdeste hangi taraftan başlanır?", ur: "وضو کس طرف سے شروع کرتے ہیں؟" },
