  // ═══ Kids Mosque Map ═══
  "kidsMosque.title": { fr: "Trouver une mosquée", en: "Find a mosque", nl: "Vind een moskee", ar: "ابحث عن مسجد", tr: "Cami bul", ur: "مسجد تلاش کریں" },
  "kidsMosque.subtitle": { fr: "Découvre les mosquées près de chez toi (toujours avec Papa/Maman)", en: "Discover mosques near you (always with Mom/Dad)", nl: "Ontdek moskeeën bij jou in de buurt (altijd met Papa/Mama)", ar: "اكتشف المساجد القريبة منك (دائماً مع ماما/بابا)", tr: "Yakınındaki camileri keşfet (her zaman anne/babayla)", ur: "اپنے قریب مساجد دریافت کریں (ہمیشہ ماں/باپ کے ساتھ)" },
  "kidsMosque.geoExplain": { fr: "Pour trouver les mosquées proches, on a besoin de ta position. On ne l'enregistre nulle part, promis !", en: "To find nearby mosques, we need your location. We don't store it anywhere, promise!", nl: "Om moskeeën in de buurt te vinden, hebben we je locatie nodig. We slaan het nergens op, beloofd!", ar: "لإيجاد المساجد القريبة، نحتاج موقعك. لن نحفظه في أي مكان، وعد!", tr: "Yakın camileri bulmak için konumuna ihtiyacımız var. Hiçbir yere kaydetmiyoruz, söz!", ur: "قریبی مساجد تلاش کرنے کے لیے آپ کے مقام کی ضرورت ہے۔ ہم اسے کہیں محفوظ نہیں کرتے، وعدہ!" },
  "kidsMosque.allowGeo": { fr: "Autoriser ma position", en: "Allow my location", nl: "Sta mijn locatie toe", ar: "السماح بموقعي", tr: "Konumuma izin ver", ur: "میرا مقام اجازت دیں" },
  "kidsMosque.locating": { fr: "Recherche de ta position…", en: "Finding your location…", nl: "Je locatie zoeken…", ar: "جارٍ البحث عن موقعك…", tr: "Konumun bulunuyor…", ur: "آپ کا مقام تلاش ہو رہا ہے…" },
  "kidsMosque.geoDenied": { fr: "On n'a pas pu accéder à ta position. Tu peux quand même utiliser la Qibla et les horaires de prière !", en: "We couldn't access your location. You can still use the Qibla and prayer times!", nl: "We konden je locatie niet bereiken. Je kunt nog steeds de Qibla en gebedstijden gebruiken!", ar: "لم نتمكن من الوصول إلى موقعك. لا يزال بإمكانك استخدام القبلة ومواقيت الصلاة!", tr: "Konumuna erişemedik. Yine de Kıble ve namaz vakitlerini kullanabilirsin!", ur: "ہم آپ کے مقام تک رسائی نہیں کر سکے۔ آپ پھر بھی قبلہ اور نماز کے اوقات استعمال کر سکتے ہیں!" },
  "kidsMosque.goQibla": { fr: "Aller à Qibla & Prières", en: "Go to Qibla & Prayers", nl: "Ga naar Qibla & Gebeden", ar: "الذهاب إلى القبلة والصلاة", tr: "Kıble & Namaza git", ur: "قبلہ اور نماز پر جائیں" },
  "kidsMosque.searching": { fr: "Recherche des mosquées…", en: "Searching for mosques…", nl: "Moskeeën zoeken…", ar: "جارٍ البحث عن المساجد…", tr: "Camiler aranıyor…", ur: "مساجد تلاش ہو رہی ہیں…" },
  "kidsMosque.fetchError": { fr: "Impossible de charger les mosquées. Réessaie plus tard 🤲", en: "Couldn't load mosques. Try again later 🤲", nl: "Kon moskeeën niet laden. Probeer later opnieuw 🤲", ar: "تعذر تحميل المساجد. حاول لاحقاً 🤲", tr: "Camiler yüklenemedi. Daha sonra tekrar dene 🤲", ur: "مساجد لوڈ نہیں ہو سکیں۔ بعد میں دوبارہ کوشش کریں 🤲" },
